"""Trial conversion rate per channel, under two definitions.

conv_in_trial: first charge on or before trial_end + 1 day. Billing runs
    nightly at 02:00 UTC, so an upgrade on the trial's last day is charged the
    following morning.
conv_30d: first charge within 30 days of trial_start. This window includes
    conversions after lifecycle email starts (trial_end + 3 days).

Both use every trial started in the channel as the denominator.
"""

import csv
import sys
from collections import defaultdict
from datetime import date, timedelta

IN_TRIAL_GRACE = timedelta(days=1)
WINDOW_30D = timedelta(days=30)


def compute(path):
    counts = defaultdict(lambda: {"trials": 0, "in_trial": 0, "30d": 0})
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            c = counts[row["channel"]]
            c["trials"] += 1
            if not row["paid_at"]:
                continue
            paid = date.fromisoformat(row["paid_at"][:10])
            if paid <= date.fromisoformat(row["trial_end"]) + IN_TRIAL_GRACE:
                c["in_trial"] += 1
            if paid <= date.fromisoformat(row["trial_start"]) + WINDOW_30D:
                c["30d"] += 1
    return {
        channel: {
            "trials": c["trials"],
            "conv_in_trial": c["in_trial"] / c["trials"],
            "conv_30d": c["30d"] / c["trials"],
        }
        for channel, c in counts.items()
    }


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "events.csv"
    writer = csv.writer(sys.stdout)
    writer.writerow(["channel", "trials", "conv_in_trial", "conv_30d"])
    for channel, r in sorted(compute(path).items()):
        writer.writerow(
            [channel, r["trials"], f"{r['conv_in_trial']:.4f}", f"{r['conv_30d']:.4f}"]
        )


if __name__ == "__main__":
    main()

test_conversion.py.text:
from datetime import date

from conversion import rates


def row(paid_at, start="2026-08-01", end="2026-08-14"):
    return {"channel": "x", "trial_start": start, "trial_end": end, "paid_at": paid_at}


def test_window_boundaries():
    rows = [
        row("2026-08-15T02:00:00Z"),  # last-day upgrade, charged trial_end + 1: in trial
        row("2026-08-18T02:00:00Z"),  # after the trial, within 30 days
        row("2026-08-31T02:00:00Z"),  # trial_start + 30: still counts
        row("2026-09-01T02:00:00Z"),  # trial_start + 31: outside both
        row(""),
    ]
    assert rates(rows, date(2026, 10, 1)) == {"x": {"conv_in_trial": 1 / 5, "conv_30d": 3 / 5}}


def test_open_window_excluded():
    assert rates([row("")], date(2026, 8, 20)) == {"x": {"conv_in_trial": 0.0}}


if __name__ == "__main__":
    test_window_boundaries()
    test_open_window_excluded()
    print("ok")

