"""Trial conversion rates per channel.

conv_in_trial: charged by the billing run after the trial's last day, so
    last-day upgrades (charged at 02:00 UTC the next day) count.
conv_30d: charged by the billing run 30 days after trial start. Includes
    post-trial conversions, which overlap with lifecycle email (it starts
    three days after the trial ends).
"""

import csv
import sys
from collections import defaultdict
from datetime import date, datetime, time, timedelta, timezone

BILLING_RUN = time(2, 0, tzinfo=timezone.utc)


def billing_cutoff(day):
    return datetime.combine(day, BILLING_RUN)


def compute(path):
    counts = defaultdict(lambda: {"trials": 0, "in_trial": 0, "30d": 0})
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            c = counts[row["channel"]]
            c["trials"] += 1
            if not row["paid_at"]:
                continue
            paid_at = datetime.fromisoformat(row["paid_at"].replace("Z", "+00:00"))
            trial_start = date.fromisoformat(row["trial_start"])
            trial_end = date.fromisoformat(row["trial_end"])
            if paid_at <= billing_cutoff(trial_end + timedelta(days=1)):
                c["in_trial"] += 1
            if paid_at <= billing_cutoff(trial_start + timedelta(days=30)):
                c["30d"] += 1
    return {
        channel: {
            "trials": c["trials"],
            "conv_in_trial": c["in_trial"] / c["trials"],
            "conv_30d": c["30d"] / c["trials"],
        }
        for channel, c in counts.items()
    }


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "events.csv"
    rates = compute(path)
    writer = csv.writer(sys.stdout)
    writer.writerow(["channel", "trials", "conv_in_trial", "conv_30d"])
    for channel in sorted(rates):
        r = rates[channel]
        writer.writerow(
            [channel, r["trials"], f"{r['conv_in_trial']:.4f}", f"{r['conv_30d']:.4f}"]
        )


if __name__ == "__main__":
    main()
